import React, {Component} from 'react';
import {Dimensions, Image, Text, TouchableNativeFeedback, View} from 'react-native';
import {connect} from 'react-redux';
import {bindActionCreators} from 'redux';
import styles from "./TestStyles";
import NavigationBar from '../../Basic/NavigationBar';
import {AnimatedCircularProgress} from 'react-native-circular-progress';
import {enterReviewMode, goToTestSection} from "../../../Redux/Playground/Test";
import firebase from 'react-native-firebase';
import firebaseApp from '../../Firebase.js';

firebaseApp.analytics().setCurrentScreen("TestPerformance");

const screen = Dimensions.get('window');

class TestPerformance extends Component<{}> {
  render() {
    firebaseApp.analytics().logEvent('Performance_Loaded', 
    {Correct: this.props.test.answers.filter(
                      (answer, index) => this.props.test.correctAnswers[index] === answer
                    ).length,
    Incorrect: this.props.test.answers.filter(
                      (answer, index) => answer !== -1 && this.props.test.correctAnswers[index] !== answer
                    ).length,
    Unanswered: this.props.test.answers.filter(
                      (answer, index) => answer === -1
                    ).length
                     } );
    return (
      <View style={styles.container}>
        <Image
          style={{
            position: 'absolute',
            flex: 1,
            width: '100%',
            height: '100%',
          }}
          source={{uri: 'data:image/jpeg;base64,'}}
        />
        <NavigationBar noDashboard={true} leftButtonStyle={'MENU_WHITE'} rightButtonStyle={'NONE'}/>
        <View style={styles.scoreContainer}>
          <View style={styles.leftBig}>
            <Text style={styles.leftBigText}>
              {
                this.props.test.answers.filter(
                  (answer, index) => this.props.test.correctAnswers[index] === answer
                ).length
              }
            </Text>
          </View>
          <View style={styles.rightSplit}>
            <Text style={styles.rightSplitText}>SCORE</Text>
            <Text style={styles.rightSplitTextBottom}>/{this.props.test.qa.length}</Text>
          </View>
        </View>
        <View style={styles.testPerformanceReview}>
          <View style={styles.performanceOffset}>
            <View style={styles.statsContainer}>
              <View style={styles.statItem}>
                <Image
                  style={styles.statIcon}
                  source={{uri: 'data:image/png;base64,'}}
                />
                <Text style={styles.stat}>
                  {
                    this.props.test.answers.filter(
                      (answer, index) => this.props.test.correctAnswers[index] === answer
                    ).length
                  }
                </Text>
                <Text style={styles.statLabel}>Correct</Text>
              </View>
              <View style={styles.statItem}>
                <Image
                  style={styles.statIcon}
                  resizeMode={'contain'}
                  source={{uri: 'data:image/png;base64,'}}
                />
                <Text style={styles.stat}>
                  {
                    this.props.test.answers.filter(
                      (answer, index) => answer === -1
                    ).length
                  }
                </Text>
                <Text style={styles.statLabel}>Unanswered</Text>
              </View>
              <View style={styles.statItem}>
                <Image
                  style={styles.statIcon}
                  source={{uri: 'data:image/png;base64,'}}
                />
                <Text style={styles.stat}>
                  {
                    this.props.test.answers.filter(
                      (answer, index) => answer !== -1 && this.props.test.correctAnswers[index] !== answer
                    ).length
                  }
                </Text>
                <Text style={styles.statLabel}>Incorrect</Text>
              </View>
            </View>
            <View style={styles.timeIndicator}>
              <Image
                style={{
                  position: 'absolute',
                  height: '100%',
                  width: '100%',
                }}
                source={{uri: 'data:image/png;base64,'}}
                resizeMode={'contain'}
              />
              <View style={styles.timeIndicatorIconWrapper}>
                <Image
                  style={styles.timeIndicatorIcon}
                  source={{uri: 'data:image/png;base64,'}}
                />
              </View>
              <View style={styles.timeIndicatorTextWrapper}>
                <Text style={styles.timeIndicatorText}>
                  {this.props.test.selectedTime === 12 ? '30 Minutes' : '1 Hour'}
                </Text>
              </View>
            </View>
            <View style={styles.pointsContainer}>
              <View style={styles.circularIndicatorBackground}/>
              <AnimatedCircularProgress
                size={screen.width / 3}
                width={10}
                fill={
                  this.props.test.answers.filter(
                    (answer, index) => this.props.test.correctAnswers[index] === answer
                  ).length * 100 / this.props.test.qa.length
                }
                linecap={'round'}
                rotation={180}
                friction={3}
                tension={10}
                tintColor="#fbc09f"
                onAnimationComplete={() => console.log('onAnimationComplete')}
                backgroundColor="#9357c5"/>
              <View style={styles.tickContainer}>
                <Image
                  style={styles.tickIcon}
                  source={{uri: 'data:image/png;base64,'}}
                />
              </View>
              <View style={styles.pointsScoreContainer}>
                <Text style={styles.pointScoreValue}>{
                  Math.round(this.props.test.answers.filter(
                    (answer, index) => this.props.test.correctAnswers[index] === answer
                  ).length * 1000 / this.props.test.qa.length) / 10
                }%</Text>
              </View>
            </View>
          </View>
          <View style={styles.testControls}>
            <Image
              style={{
                opacity: 0.5,
                borderTopLeftRadius: 0.05 * screen.width,
                borderTopRightRadius: 0.05 * screen.width,
                position: 'absolute',
                height: '100%',
                width: '100%',
                top: 0,
              }}
              resizeMode={'cover'}
              source={{uri: 'data:image/png;base64,'}}
            />
            <TouchableNativeFeedback
              onPress={() => {
                this.props.enterReviewMode();
                firebaseApp.analytics().logEvent('Review_Mode');
                this.props.history.push('/test/ongoingTest')
              }}
            >
              <View style={styles.testControlButton}>
                <Image
                  style={[styles.timeIndicatorIcon, {margin: 0.02 * screen.width}]}
                  source={{uri: 'data:image/png;base64,'}}
                />
                <Text style={styles.testControlButtonText}>
                  Review
                </Text>
              </View>
            </TouchableNativeFeedback>
            <TouchableNativeFeedback
              onPress={() => 
                {
                  this.props.goToTestSection();
                  firebaseApp.analytics().logEvent('Another_Test');
                  this.props.history.push('/test')}
                }
            >
              <View style={styles.testControlButton}>
                <Image
                  style={[styles.timeIndicatorIcon, {margin: 0.02 * screen.width}]}
                  source={{uri: 'data:image/png;base64,'}}
                />
                <Text style={styles.testControlButtonText}>
                  Another Test
                </Text>
              </View>
            </TouchableNativeFeedback>
          </View>
          <TouchableNativeFeedback
            onPress={() => this.props.history.push('/')}
          >
            <View style={styles.backToMainButton}>
              <Image
                style={{
                  position: 'absolute',
                  height: '100%',
                  width: '100%',
                  top: 0,
                }}
                resizeMode={'cover'}
                source={{uri: 'data:image/png;base64,'}}
              />
              <Text style={styles.backToMainButtonText}>
                Back To Home
              </Text>
            </View>
          </TouchableNativeFeedback>
        </View>
      </View>
    )
  }
}

const mapStateToProps = state => ({
  test: state.test,
});
const mapDispatchToProps = dispatch => bindActionCreators({
  goToTestSection: goToTestSection,
  enterReviewMode: enterReviewMode,
}, dispatch);

export default connect(mapStateToProps, mapDispatchToProps)(TestPerformance);
